	/** SUM over an arithmetic expression: erroring inputs ("abc" + 1, "1" + 1) are skipped like the generic arm. */
	@Test
	public void sumOverExpressionCompilesNativelyAndSkipsErrorInputs() {
		String query = "SELECT (SUM(?v + 1) AS ?sum) WHERE { ?s <" + EX + "val> ?v }";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(((Literal) rows.get(0).getValue("sum")).longValue()).isEqualTo(9L);
			assertThat(rows.get(0).getBindingNames()).containsExactly("sum");
		}
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("SUM over an expression must compile natively (previously a root decline)")
				.isGreaterThanOrEqualTo(1);
	}

	/** DISTINCT applies to the computed value: STR collapses "1"^^xsd:integer and "1" into one member. */
	@Test
	public void countDistinctOverExpressionDeduplicatesComputedValues() {
		String distinct = "SELECT (COUNT(DISTINCT STR(?v)) AS ?c) WHERE { ?s <" + EX + "val> ?v }";
		String plain = "SELECT (COUNT(STR(?v)) AS ?c) WHERE { ?s <" + EX + "val> ?v }";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(distinct).evaluate());
			assertThat(((Literal) rows.get(0).getValue("c")).longValue()).isEqualTo(4L);
			List<BindingSet> plainRows = QueryResults.asList(conn.prepareTupleQuery(plain).evaluate());
			assertThat(((Literal) plainRows.get(0).getValue("c")).longValue()).isEqualTo(5L);
		}
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("COUNT(DISTINCT expr) must compile natively")
				.isGreaterThanOrEqualTo(2);
	}

	@Test
	public void distinctBindOverValuesRetainsBindSourceRows() {
		String query = "SELECT (COUNT(DISTINCT ?x) AS ?c) WHERE { "
				+ "VALUES ?v { 1 2 } BIND(?v AS ?x) }";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(((Literal) rows.get(0).getValue("c")).longValue())
					.as("both VALUES rows remain live through the BIND dependency")
					.isEqualTo(2L);
		}
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("the regression must exercise the native aggregate planner")
				.isGreaterThanOrEqualTo(1);
	}

	@Test
	public void aggregateCallsInHavingStayOnTheNativeGroupPath() {
		String query = "SELECT ?s (COUNT(?v) AS ?c) WHERE { ?s <" + EX
				+ "val> ?v } GROUP BY ?s HAVING (COUNT(?v) >= 1)";
		List<BindingSet> expected;
		System.setProperty(NATIVE_FLAG, "false");
		try (SailRepositoryConnection conn = repository.getConnection()) {
			expected = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			System.setProperty(NATIVE_FLAG, "true");
		}

		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			assertThat(QueryResults.asList(conn.prepareTupleQuery(query).evaluate()))
					.containsExactlyInAnyOrderElementsOf(expected);
		}
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
				.as("GROUP and HAVING must be compiled as one semantic-native aggregate root")
				.isZero();
	}

	@Test
	public void avgOverProtectedExpressionCompilesAsAggregateInsteadOfScalarExtension() {
		String query = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#> "
				+ "SELECT (AVG(IF(isNumeric(?v), ?v, COALESCE(xsd:double(?v), 0))) AS ?avg) "
				+ "WHERE { ?s <" + EX + "val> ?v }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).singleElement().satisfies(row -> {
				assertThat(row.getBindingNames()).containsExactly("avg");
				assertThat(((Literal) row.getValue("avg")).doubleValue()).isEqualTo(1.4D);
			});
		}
	}

	/** Grouped MIN over an expression; the all-error group omits its aggregate binding like the generic arm. */
	@Test
	public void groupedMinOverExpressionOmitsBindingForErrorOnlyGroups() {
		String query = "SELECT ?s (MIN(?v * 2) AS ?m) WHERE { ?s <" + EX + "val> ?v } GROUP BY ?s";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(5);
			for (BindingSet row : rows) {
				String subject = row.getValue("s").stringValue();
				if (subject.endsWith("s4") || subject.endsWith("s5")) {
					assertThat(row.hasBinding("m")).as("all-error group omits the binding").isFalse();
				} else {
					long expected = 2L * Long.parseLong(subject.substring(subject.length() - 1));
					assertThat(((Literal) row.getValue("m")).longValue()).isEqualTo(expected);
				}
				assertThat(row.getBindingNames()).doesNotContain("#aggExpr0");
			}
		}
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("grouped MIN over an expression must compile natively")
				.isGreaterThanOrEqualTo(1);
	}

